import * as React from "react"

const MOBILE_BREAKPOINT = 768

const query = `(max-width: ${MOBILE_BREAKPOINT - 1}px)`

function subscribe(onChange: () => void) {
  const mql = window.matchMedia(query)
  mql.addEventListener("change", onChange)
  return () => mql.removeEventListener("change", onChange)
}

/**
 * Generated by the shadcn CLI, edited deliberately (docs/conventions.md §4).
 *
 * The shipped version calls `setState` inside an effect, which the React Compiler lint
 * rejects as a cascading render. `useSyncExternalStore` is the same behaviour expressed
 * as what it actually is — a subscription to a platform API — and it gives the server
 * render a defined answer (desktop) instead of `undefined`.
 *
 * Re-running the CLI will revert this. Reapply it.
 */
export function useIsMobile() {
  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  )
}
